 * runtime. Mirrors ``tools/i18n/locales.json`` exactly; ``coverage`` is computed from the
 * actual resource files by the generator, never stored.
 */
@Suppress("unused")
data class SupportedLocale(
    val id: String,
    /** BCP-47 runtime tag; the picker's System-default row writes the empty tag. */
    val languageTag: String,
    /** Android resource directory qualifier, e.g. `pt` or `zh-rCN`. */
    val resourceQualifier: String,
    /** Legacy Weblate code; kept because this is a published data class. */
    val weblateCode: String,
    val englishName: String,
    val endonym: String,
    /** ISO 15924 script code, e.g. `Latn`, `Arab`, `Cyrl`, `Hans`. */
    val script: String,
    val rtl: Boolean,
    val tier: Int,
    val packaged: Boolean,
    val pickerVisible: Boolean,
    /** Computed coverage of translatable source keys, 0..100. */
    val coverage: Int,
)

@Suppress("unused")
object SupportedLocales {

    /** A locale needs this coverage before the picker may show it. */
    const val TRANSLATION_READINESS_THRESHOLD_PERCENT: Int = 75

    /** Project page the app opens from its help-translate dialog. */
    const val CONTRIBUTION_PROJECT_URL: String = "https://hosted.weblate.org/projects/owntv/"

    /** Canonical issue form for requesting a locale before its base files exist. */
    const val LANGUAGE_REQUEST_URL: String = "https://github.com/ahXN00/OwnTV/issues/new?template=feature_request.yml&title=%5BLanguage%5D%20Add%20"

    /** Tag meaning "follow the current device locale list" (see ``LocaleStore``). */
    const val SYSTEM_DEFAULT_TAG: String = ""

    val all: List<SupportedLocale> = listOf(
        SupportedLocale(
            id = "en-US",
            languageTag = "en-US",
            resourceQualifier = "en",
            weblateCode = "en",
            englishName = "English",
            endonym = "English",
            script = "Latn",
            rtl = false,
            tier = 1,
            packaged = true,
            pickerVisible = true,
            coverage = 100,
        ),
        SupportedLocale(
            id = "zh-CN",
            languageTag = "zh-CN",
            resourceQualifier = "zh-rCN",
            weblateCode = "zh_Hans",
            englishName = "Chinese (Simplified)",
            endonym = "简体中文",
            script = "Hans",
            rtl = false,
            tier = 1,
            packaged = true,
            pickerVisible = true,
            coverage = 100,
        ),
        SupportedLocale(
            id = "zh-TW",
            languageTag = "zh-TW",
            resourceQualifier = "zh-rTW",
            weblateCode = "zh_Hant",
            englishName = "Chinese (Traditional)",
            endonym = "繁體中文",
            script = "Hant",
            rtl = false,
            tier = 1,
            packaged = true,
            pickerVisible = true,
            coverage = 100,
        ),
    )

    /** Rows the in-app picker may show. */
    val pickerRows: List<SupportedLocale> get() = all.filter {
        (it.id == "en-US" || it.coverage >= TRANSLATION_READINESS_THRESHOLD_PERCENT) &&
            it.packaged && it.pickerVisible
    }

    /** True when coverage clears the readiness threshold. */
    fun isTranslationReady(coverage: Int): Boolean =
        coverage >= TRANSLATION_READINESS_THRESHOLD_PERCENT

    /** Visible badge for a partially translated locale; the source row has none. */
    fun coverageBadgePercent(locale: SupportedLocale): Int? =
        locale.coverage.takeIf { locale.tier == 1 && locale.id != "en-US" && locale.pickerVisible && it < 100 }

    /** Canonicalize a supported runtime tag; empty means follow the system locale. */
    fun canonicalTag(raw: String?): String? {
        val trimmed = raw?.trim() ?: return null
        if (trimmed.isEmpty()) return SYSTEM_DEFAULT_TAG
        return all.firstOrNull { it.languageTag.equals(trimmed, ignoreCase = true) }?.languageTag
    }

    /** Look up the ISO 15924 script for a BCP-47 tag, or null if it is not a catalogue entry. */
    fun scriptForTag(tag: String): String? =
        all.firstOrNull { it.languageTag == tag }?.script

    /** True for an RTL script (Arabic, ...). False for the system-default empty tag. */
    fun isRtl(tag: String): Boolean = all.firstOrNull { it.languageTag == tag }?.rtl == true
}
